using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Web.Script.Serialization;
using System.Windows;
using System.Windows.Controls;
using Microsoft.Win32;
using ClinicQueueSystem.Models;
using ClinicQueueSystem.Services;

namespace ClinicQueueSystem
{
 public partial class AdminWindow : Window
 {
  private readonly User _admin;
  private static readonly JavaScriptSerializer Serializer = new JavaScriptSerializer { MaxJsonLength = 20 * 1024 * 1024, RecursionLimit = 100 };
  public AdminWindow(User admin) { InitializeComponent(); _admin = admin; if (admin == null || admin.Role != "ADMIN") { MessageBox.Show("Administrator access required."); Close(); return; } StoragePathText.Text = JsonStore.FilePath; ClinicNameBox.Text=JsonStore.Data.ClinicName; TicketFooterBox.Text=JsonStore.Data.TicketFooter; RefreshAll(); LoadJsonText(); }
  private void RefreshAll() { DepartmentsGrid.ItemsSource = null; DepartmentsGrid.ItemsSource = JsonStore.Data.Departments; DoctorsGrid.ItemsSource = null; DoctorsGrid.ItemsSource = JsonStore.Data.Doctors; ShiftsGrid.ItemsSource = null; ShiftsGrid.ItemsSource = JsonStore.Data.Shifts; CountersGrid.ItemsSource = null; CountersGrid.ItemsSource = JsonStore.Data.Counters; PrintersGrid.ItemsSource = null; PrintersGrid.ItemsSource = JsonStore.Data.Printers; UsersGrid.ItemsSource = null; UsersGrid.ItemsSource = JsonStore.Data.Users.Select(u => new UserRow { Username=u.Username, FullName=u.FullName, Role=u.Role, Active=u.Active }).ToList(); TicketsGrid.ItemsSource = null; TicketsGrid.ItemsSource = JsonStore.Data.Tickets.OrderByDescending(t=>t.Date).ThenByDescending(t=>t.Time).ToList(); AuditGrid.ItemsSource = null; AuditGrid.ItemsSource = JsonStore.Data.Audit.OrderByDescending(a=>a.At).ToList(); }
  private void SaveMaster_Click(object s, RoutedEventArgs e) { try { CommitGrids(); ValidateData(JsonStore.Data); JsonStore.Save(); QueueService.Log(_admin.Username,"ADMIN_SAVE_MASTER_DATA","Saved master records"); JsonStore.Save(); RefreshAll(); LoadJsonText(); StatusText.Text="Changes saved successfully."; } catch(Exception ex) { MessageBox.Show(ex.Message,"Cannot save changes",MessageBoxButton.OK,MessageBoxImage.Error); } }
  private void CommitGrids() { foreach(var g in new[]{DepartmentsGrid,DoctorsGrid,ShiftsGrid,CountersGrid,PrintersGrid,UsersGrid}) { g.CommitEdit(DataGridEditingUnit.Cell,true); g.CommitEdit(DataGridEditingUnit.Row,true); } var rows=UsersGrid.ItemsSource as System.Collections.Generic.IEnumerable<UserRow>; if(rows!=null) foreach(var r in rows){var u=JsonStore.Data.Users.FirstOrDefault(x=>string.Equals(x.Username,r.Username,StringComparison.OrdinalIgnoreCase)); if(u!=null){u.FullName=r.FullName;u.Role=NormalizeRole(r.Role);u.Active=r.Active;}} }
  private static string NormalizeRole(string role) { var r=(role??"").Trim().ToUpperInvariant(); if(r!="ADMIN"&&r!="RECEPTIONIST") throw new InvalidOperationException("Only ADMIN and RECEPTIONIST roles are allowed."); return r; }
  private void ValidateData(AppData d) { if(d.Departments.Any(x=>string.IsNullOrWhiteSpace(x.Code)||string.IsNullOrWhiteSpace(x.Name))) throw new InvalidOperationException("Every department needs a code and name."); if(d.Departments.GroupBy(x=>x.Code,StringComparer.OrdinalIgnoreCase).Any(g=>g.Count()>1)) throw new InvalidOperationException("Department codes must be unique."); if(d.Users.Any(x=>string.IsNullOrWhiteSpace(x.Username)||string.IsNullOrWhiteSpace(x.PasswordHash))) throw new InvalidOperationException("Every user needs a username and password hash."); if(d.Users.GroupBy(x=>x.Username,StringComparer.OrdinalIgnoreCase).Any(g=>g.Count()>1)) throw new InvalidOperationException("Usernames must be unique."); foreach(var u in d.Users) u.Role=NormalizeRole(u.Role); if(!d.Users.Any(u=>u.Active&&u.Role=="ADMIN")) throw new InvalidOperationException("At least one active administrator must remain."); if(d.Departments.Any(x=>x.DefaultPrice<0)||d.Doctors.Any(x=>x.DefaultPrice<0)) throw new InvalidOperationException("Prices cannot be negative."); }
  private void AddDepartment_Click(object s,RoutedEventArgs e) { var d=new Department{Code="NEW",Name="New department",DefaultPrice=0,Active=true}; JsonStore.Data.Departments.Add(d); RefreshAll(); DepartmentsGrid.SelectedItem=d; }
  private void AddDoctor_Click(object s,RoutedEventArgs e) { var d=new Doctor{Name="New doctor",DepartmentCode="",DefaultPrice=0,Active=true}; JsonStore.Data.Doctors.Add(d); RefreshAll(); DoctorsGrid.SelectedItem=d; }
  private void AddShift_Click(object s,RoutedEventArgs e) { var x=new Shift{Name="New shift",StartTime="08:00",EndTime="14:00",Active=true}; JsonStore.Data.Shifts.Add(x); RefreshAll(); ShiftsGrid.SelectedItem=x; }
  private void AddCounter_Click(object s,RoutedEventArgs e) { var x=new Counter{Name="Counter 02",PrinterName="",Active=true}; JsonStore.Data.Counters.Add(x); RefreshAll(); CountersGrid.SelectedItem=x; }
  private void AddPrinter_Click(object s,RoutedEventArgs e) { var x=new PrinterConfig{Name="New printer",WindowsPrinterName="",PaperWidthMm=80,Active=true}; JsonStore.Data.Printers.Add(x); RefreshAll(); PrintersGrid.SelectedItem=x; }
  private void DeleteDepartment_Click(object s,RoutedEventArgs e) { DeleteSelected(DepartmentsGrid,JsonStore.Data.Departments,"department"); }
  private void DeleteDoctor_Click(object s,RoutedEventArgs e) { DeleteSelected(DoctorsGrid,JsonStore.Data.Doctors,"doctor"); }
  private void DeleteShift_Click(object s,RoutedEventArgs e) { DeleteSelected(ShiftsGrid,JsonStore.Data.Shifts,"shift"); }
  private void DeleteCounter_Click(object s,RoutedEventArgs e) { DeleteSelected(CountersGrid,JsonStore.Data.Counters,"counter"); }
  private void DeletePrinter_Click(object s,RoutedEventArgs e) { DeleteSelected(PrintersGrid,JsonStore.Data.Printers,"printer"); }
  private void DeleteSelected<T>(DataGrid grid,System.Collections.Generic.List<T> list,string label) { var item=grid.SelectedItem as T; if(item==null){MessageBox.Show("Select a "+label+" first.");return;} if(MessageBox.Show("Delete this "+label+"?","Confirm delete",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return; list.Remove(item); RefreshAll(); }
  private void AddUser_Click(object s,RoutedEventArgs e) { var dlg=new UserEditorWindow(null){Owner=this}; if(dlg.ShowDialog()==true){if(JsonStore.Data.Users.Any(u=>u.Username.Equals(dlg.Result.Username,StringComparison.OrdinalIgnoreCase))){MessageBox.Show("That username already exists.");return;}JsonStore.Data.Users.Add(dlg.Result); JsonStore.Save(); QueueService.Log(_admin.Username,"CREATE_USER",dlg.Result.Username); JsonStore.Save();RefreshAll();LoadJsonText();} }
  private void SetPassword_Click(object s,RoutedEventArgs e) { var row=UsersGrid.SelectedItem as UserRow; if(row==null){MessageBox.Show("Select a user first.");return;} var user=JsonStore.Data.Users.FirstOrDefault(u=>u.Username==row.Username); if(user==null)return; var dlg=new PasswordEditorWindow(user.Username){Owner=this}; if(dlg.ShowDialog()==true){user.PasswordHash=PasswordService.Hash(dlg.NewPassword); QueueService.Log(_admin.Username,"RESET_USER_PASSWORD",user.Username);JsonStore.Save();LoadJsonText();StatusText.Text="Password updated.";} }
  private void DeleteUser_Click(object s,RoutedEventArgs e) { var row=UsersGrid.SelectedItem as UserRow; if(row==null){MessageBox.Show("Select a user first.");return;} var u=JsonStore.Data.Users.FirstOrDefault(x=>x.Username==row.Username); if(u==null)return; if(u.Username.Equals(_admin.Username,StringComparison.OrdinalIgnoreCase)){MessageBox.Show("You cannot delete the account currently in use.");return;} if(MessageBox.Show("Delete user "+u.Username+"?","Confirm",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;JsonStore.Data.Users.Remove(u);JsonStore.Save();RefreshAll();LoadJsonText(); }
  private void SaveSettings_Click(object s,RoutedEventArgs e){JsonStore.Data.ClinicName=(ClinicNameBox.Text??"").Trim();JsonStore.Data.TicketFooter=(TicketFooterBox.Text??"").Trim();JsonStore.Save();QueueService.Log(_admin.Username,"UPDATE_CLINIC_SETTINGS","Updated clinic name/footer");JsonStore.Save();LoadJsonText();StatusText.Text="Clinic settings saved.";MessageBox.Show("Clinic settings saved.");}
  private void LoadJsonText(){JsonEditor.Text=Serializer.Serialize(JsonStore.Data);}
  private void ReloadJson_Click(object s,RoutedEventArgs e){LoadJsonText();StatusText.Text="Reloaded saved JSON.";}
  private void ValidateJson_Click(object s,RoutedEventArgs e){try{var d=Serializer.Deserialize<AppData>(JsonEditor.Text);if(d==null)throw new InvalidOperationException("JSON document is empty.");NormalizeLists(d);ValidateData(d);MessageBox.Show("JSON is valid and required admin/role checks passed.","Validation",MessageBoxButton.OK,MessageBoxImage.Information);}catch(Exception ex){MessageBox.Show(ex.Message,"Invalid JSON",MessageBoxButton.OK,MessageBoxImage.Error);}}
  private void SaveJson_Click(object s,RoutedEventArgs e){try{var d=Serializer.Deserialize<AppData>(JsonEditor.Text);if(d==null)throw new InvalidOperationException("JSON document is empty.");NormalizeLists(d);ValidateData(d);var old=JsonStore.Data;JsonStore.Data=d;try{JsonStore.Save();QueueService.Log(_admin.Username,"EDIT_JSON_DATA","Admin edited complete JSON data");JsonStore.Save();}catch{JsonStore.Data=old;throw;}RefreshAll();LoadJsonText();StatusText.Text="JSON saved and validated.";MessageBox.Show("JSON data saved successfully.");}catch(Exception ex){MessageBox.Show(ex.Message,"JSON not saved",MessageBoxButton.OK,MessageBoxImage.Error);}}
  private void NormalizeLists(AppData d){if(d.Users==null)d.Users=new System.Collections.Generic.List<User>();if(d.Departments==null)d.Departments=new System.Collections.Generic.List<Department>();if(d.Doctors==null)d.Doctors=new System.Collections.Generic.List<Doctor>();if(d.Shifts==null)d.Shifts=new System.Collections.Generic.List<Shift>();if(d.Counters==null)d.Counters=new System.Collections.Generic.List<Counter>();if(d.Printers==null)d.Printers=new System.Collections.Generic.List<PrinterConfig>();if(d.Tickets==null)d.Tickets=new System.Collections.Generic.List<Ticket>();if(d.Audit==null)d.Audit=new System.Collections.Generic.List<AuditEntry>();if(d.Sequences==null)d.Sequences=new System.Collections.Generic.Dictionary<string,int>();}
  private void Backup_Click(object s,RoutedEventArgs e){try{JsonStore.Save();var dlg=new SaveFileDialog{Filter="JSON backup (*.json)|*.json",FileName="clinic-backup-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".json"};if(dlg.ShowDialog()==true){File.Copy(JsonStore.FilePath,dlg.FileName,true);MessageBox.Show("Backup created.");}}catch(Exception ex){MessageBox.Show(ex.Message);}}
  private void Restore_Click(object s,RoutedEventArgs e){var dlg=new OpenFileDialog{Filter="JSON backup (*.json)|*.json"};if(dlg.ShowDialog()!=true)return;try{var d=Serializer.Deserialize<AppData>(File.ReadAllText(dlg.FileName,Encoding.UTF8));if(d==null)throw new InvalidOperationException("Backup is empty.");NormalizeLists(d);ValidateData(d);if(MessageBox.Show("Replace current clinic data with this backup?","Confirm restore",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;JsonStore.Data=d;JsonStore.Save();RefreshAll();LoadJsonText();MessageBox.Show("Backup restored.");}catch(Exception ex){MessageBox.Show(ex.Message,"Restore failed",MessageBoxButton.OK,MessageBoxImage.Error);}}
  private void OpenFolder_Click(object s,RoutedEventArgs e){try{System.Diagnostics.Process.Start("explorer.exe",JsonStore.Folder);}catch(Exception ex){MessageBox.Show(ex.Message);}}
  private void Close_Click(object s,RoutedEventArgs e)=>Close();
  private class UserRow { public string Username{get;set;} public string FullName{get;set;} public string Role{get;set;} public bool Active{get;set;} }
 }
 public class UserEditorWindow:Window { public User Result{get;private set;} private TextBox username,fullName; private PasswordBox password; private ComboBox role; public UserEditorWindow(User existing){Title="Add user";Width=470;Height=440;WindowStartupLocation=WindowStartupLocation.CenterOwner;ResizeMode=ResizeMode.NoResize;Background=System.Windows.Media.Brushes.White;var p=new StackPanel{Margin=new Thickness(26)};p.Children.Add(new TextBlock{Text="Create account",FontSize=24,FontWeight=FontWeights.Bold,Margin=new Thickness(0,0,0,18)});p.Children.Add(new TextBlock{Text="Username"});username=new TextBox{Margin=new Thickness(0,4,0,10)};p.Children.Add(username);p.Children.Add(new TextBlock{Text="Full name"});fullName=new TextBox{Margin=new Thickness(0,4,0,10)};p.Children.Add(fullName);p.Children.Add(new TextBlock{Text="Temporary password"});password=new PasswordBox{Margin=new Thickness(0,4,0,10),Padding=new Thickness(8)};p.Children.Add(password);p.Children.Add(new TextBlock{Text="Role"});role=new ComboBox{ItemsSource=new[]{"ADMIN","RECEPTIONIST"},SelectedIndex=1,Margin=new Thickness(0,4,0,14)};p.Children.Add(role);var b=new Button{Content="Create user",Background=(System.Windows.Media.Brush)new System.Windows.Media.BrushConverter().ConvertFromString("#17365D"),Foreground=System.Windows.Media.Brushes.White,Padding=new Thickness(12)};b.Click+=(s,e)=>{if(string.IsNullOrWhiteSpace(username.Text)||string.IsNullOrWhiteSpace(fullName.Text)||password.Password.Length<8){MessageBox.Show("Enter username, full name and a password of at least 8 characters.");return;}Result=new User{Username=username.Text.Trim(),FullName=fullName.Text.Trim(),Role=role.SelectedItem.ToString(),PasswordHash=PasswordService.Hash(password.Password),Active=true};DialogResult=true;};p.Children.Add(b);Content=p;}}
 public class PasswordEditorWindow:Window {public string NewPassword{get;private set;} private PasswordBox pass,confirm;public PasswordEditorWindow(string username){Title="Set password";Width=440;Height=330;WindowStartupLocation=WindowStartupLocation.CenterOwner;var p=new StackPanel{Margin=new Thickness(24)};p.Children.Add(new TextBlock{Text="Set password for "+username,FontSize=20,FontWeight=FontWeights.Bold,Margin=new Thickness(0,0,0,16)});p.Children.Add(new TextBlock{Text="New password (minimum 8 characters)"});pass=new PasswordBox{Padding=new Thickness(8),Margin=new Thickness(0,4,0,12)};p.Children.Add(pass);p.Children.Add(new TextBlock{Text="Confirm password"});confirm=new PasswordBox{Padding=new Thickness(8),Margin=new Thickness(0,4,0,16)};p.Children.Add(confirm);var b=new Button{Content="Save password",Padding=new Thickness(10)};b.Click+=(s,e)=>{if(pass.Password.Length<8||pass.Password!=confirm.Password){MessageBox.Show("Passwords must match and be at least 8 characters.");return;}NewPassword=pass.Password;DialogResult=true;};p.Children.Add(b);Content=p;}}
}
